//@ts-nocheck
import { Component, Element, Host, Prop, h } from "@stencil/core";

interface TreeNode {
	children?: TreeNode[];
	name: string; // label text on circle sector or leaf
	backgroundColor?: string; // background color for circle sector or leaf
	strokeColor?: string; // border/stroke color for circle sector or leaf
	tooltip?: {
		// tooltip for leaf
		slot?: HTMLElement; // slot or text, slot div must be defined with as <div></div> per tooltip spec
		text?: string;
		distance: number;
		containerStyle: string; // css of the tooltip, width is 100px by default and can be overrided since it is in a foreignObject in an SVG
		placement: string;
	};
	leaf?: {
		label?: {
			paddingX?: number;
			paddingY?: number;
			borderRadius?: number;
			backgroundColor?: string;
			fontSize?: number;
			lineHeight?: number;
			deltaX?: number;
			deltaY?: number;
		};
		line?: {
			color?: string;
			startPercent: number; // where polyline coming from the circle sector
			endPercent: number; // where polyline going to the label
		};
		dot: {
			size?: number;
			color?: string;
			strokeColor?: string;
			strokeWidth?: number;
		};
	};
	event?: {
		// event for leaf
		click?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
		mouseenter?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
		mouseover?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
		mouseout?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
	};
}

const POPOVER_DISTANCE = 10;
const POPOVER_PLACEMENT = "top";

type ExploreRenderModule = typeof import("./render-chart");

@Component({
	tag: "hbr-explore",
	styleUrl: "explore.scss",
	shadow: true,
})
export class HbrExploreChart {
	@Element() host: HTMLHbrExploreElement;
	tooltipRef: HTMLHbrPopoverElement;
	chartRef: HTMLElement;
	boardRef: HTMLHbrChartBoardElement;
	renderModulePromise?: Promise<ExploreRenderModule>;
	renderRequestId = 0;

	@Prop() loading = false;

	/** config set the data, width and height of the canvas, scale is to set the size of the chart */
	@Prop() config: {
		data: TreeNode /** tree object for explore data */;
		width?: number;
		height?: number;
		scale?: number;
		sector?: {
			heightDiff?: number;
			fontSize?: number;
			textUpperDelta1?: number;
			textLowerDelta1?: number;
			textUpperDelta2?: number;
			textLowerDelta2?: number;
			textUpperDelta3?: number;
			textLowerDelta3?: number;
		};
		midSector?: {
			fontSize?: string;
			padding?: string;
			width?: string;
			height?: string;
		};
		// global setting for treeNode
		leaf: {
			label?: {
				paddingX?: number;
				paddingY?: number;
				borderRadius?: number;
				backgroundColor?: string;
				fontSize?: number;
				lineHeight?: number;
				deltaX?: number;
				deltaY?: number;
			};
			line?: {
				color?: string;
				startPercent?: number;
				endPercent?: number;
			};
			dot?: {
				size?: number;
				color?: string;
				strokeColor?: string;
				strokeWidth?: number;
			};
		};
	} = {
		data: {
			name: "Empty Root",
		},
		leaf: {
			label: {
				paddingX: 20,
				paddingY: 10,
				borderRadius: 10,
				backgroundColor: "transparent",
				deltaX: 180,
				deltaY: 0,
			},
		},
		width: 720,
		height: 480,
		scale: 0.85,
		sector: {
			fontSize: 18,
			heightDiff: 0,
			textUpperDelta1: 32,
			textLowerDelta1: -18,
			textUpperDelta2: 32,
			textLowerDelta2: -18,
			textUpperDelta3: 32,
			textLowerDelta3: -18,
		},
	};

	async componentDidLoad() {
		await this.queueRenderChart();
	}

	async componentShouldUpdate() {
		await this.queueRenderChart();
	}

	getRenderModule = () => {
		if (!this.renderModulePromise) {
			this.renderModulePromise = import("./render-chart");
		}
		return this.renderModulePromise;
	};

	queueRenderChart = async () => {
		const requestId = ++this.renderRequestId;
		await this.boardRef.setChartConfig(this.config);

		setTimeout(async () => {
			if (
				requestId !== this.renderRequestId ||
				!this.chartRef ||
				!this.tooltipRef
			) {
				return;
			}

			const { renderExploreChart } = await this.getRenderModule();

			if (requestId !== this.renderRequestId) {
				return;
			}

			await renderExploreChart({
				chartRef: this.chartRef,
				tooltipRef: this.tooltipRef,
				config: this.config,
			});
		}, 50);
	};
	render() {
		return (
			<Host>
				<hbr-chart-board
					ref={(el) => {
						this.boardRef = el;
					}}
					isLoading={this.loading}
					style={{ width: "100%", height: "100%" }}
				>
					<hbr-popover
						distance={POPOVER_DISTANCE}
						anchor=""
						ref={(el) => {
							this.tooltipRef = el;
						}}
						part="popover"
						variant="chart"
						placement={POPOVER_PLACEMENT}
					>
						<div slot="content">
							<div style={{ display: "flex", justifyContent: "space-between" }}>
								<div
									style={{ display: "flex", alignItems: "center", gap: "6px" }}
								>
									<div
										class="color"
										style={{ width: "16px", height: "16px", background: "" }}
									/>
									<span />
								</div>
								<div>
									<span />
								</div>
							</div>
						</div>
					</hbr-popover>
					<div
						style={{ width: "100%", height: "100%" }}
						ref={(el) => {
							this.chartRef = el;
						}}
						class="--hbr-explore"
						part="chart"
					/>
					<div slot="footer">
						<slot name="footer" />
					</div>
					<div slot="loading-state">
						<slot name="loading-state" />
					</div>
					<div slot="empty-state">
						<slot name="empty-state" />
					</div>
				</hbr-chart-board>
			</Host>
		);
	}
}
